package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/user/new", func(c *gin.Context) { c.String(200, "静态路由") })
	r.GET("/user/:id", func(c *gin.Context) { c.String(200, "参数路由 id="+c.Param("id")) })
	r.GET("/files/*path", func(c *gin.Context) { c.String(200, "通配路由 path="+c.Param("path")) })

	for _, path := range []string{"/user/new", "/user/42", "/files/a/b.txt"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest("GET", path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-16s -> %s\n", path, w.Body.String())
	}
}

package main

import (
	"fmt"

	"github.com/gin-gonic/gin"
)

func register(name string, fn func()) {
	defer func() {
		if err := recover(); err != nil {
			fmt.Printf("%s: panic = %v\n", name, err)
			return
		}
		fmt.Printf("%s: 没有 panic\n", name)
	}()
	fn()
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	register("同名参数", func() {
		r := gin.New()
		r.GET("/user/:id", func(c *gin.Context) {})
		r.GET("/user/:name", func(c *gin.Context) {})
	})

	register("通配与静态段冲突", func() {
		r := gin.New()
		r.GET("/files/*path", func(c *gin.Context) {})
		r.GET("/files/x", func(c *gin.Context) {})
	})

	register("同一路径重复注册", func() {
		r := gin.New()
		r.GET("/a", func(c *gin.Context) {})
		r.GET("/a", func(c *gin.Context) {})
	})
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	api := r.Group("/api", func(c *gin.Context) {
		fmt.Println("api 组的中间件")
		c.Next()
	})
	api.GET("/hello", func(c *gin.Context) {
		fmt.Println("/api/hello 的处理函数")
		c.String(200, "hello")
	})

	// 组外注册的路由不会经过组里的中间件
	r.GET("/plain", func(c *gin.Context) { c.String(200, "plain") })

	for _, path := range []string{"/api/hello", "/plain"} {
		fmt.Println("--", path)
		w := httptest.NewRecorder()
		req := httptest.NewRequest("GET", path, nil)
		r.ServeHTTP(w, req)
		fmt.Println("响应:", w.Body.String())
	}
}

