		fmt.Println("处理函数")
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/api/x", nil)
	r.ServeHTTP(w, req)
	fmt.Println("状态码:", w.Code)
}

