package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(func(c *gin.Context) {
		if c.GetHeader("X-Token") == "" {
			// 写响应 + Abort：后面的处理函数不会再执行
			c.AbortWithStatusJSON(401, gin.H{"error": "缺少 token"})
			return
		}
		c.Next()
	})
	r.GET("/secret", func(c *gin.Context) { c.String(200, "机密内容") })

	for _, token := range []string{"", "abc"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest("GET", "/secret", nil)
		if token != "" {
			req.Header.Set("X-Token", token)
		}
		r.ServeHTTP(w, req)
		fmt.Printf("token=%q -> code=%d body=%s\n", token, w.Code, w.Body.String())
	}
}

