		c.String(200, fmt.Sprintf("%v/%d", id, c.GetInt("user_id")))
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/who", nil)
	r.ServeHTTP(w, req)
	fmt.Println("响应:", w.Body.String())
}

