import (
	"fmt"
	"log"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// Logger 记录方法、路由模板、状态码和耗时
func Logger() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next()
		log.Printf("%s %s -> %d (%s)",
			c.Request.Method,
			c.FullPath(), // 路由模板，不是原始路径
			c.Writer.Status(),
			time.Since(start),
		)
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(Logger())
	r.GET("/user/:id", func(c *gin.Context) { c.String(200, "ok") })

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/user/7", nil)
	r.ServeHTTP(w, req)
	fmt.Println("状态码:", w.Code)
}

