import (
	"fmt"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// Cost 统计整条 handler 链的耗时
func Cost() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		defer func() {
			cost := time.Since(start)
			c.Set("cost", cost) // 存进 Context，其实链已经走完没人会读
			fmt.Printf("%s 耗时 %s\n", c.FullPath(), cost)
		}()
		c.Next() // 先让后面的处理函数跑完
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(Cost())
	r.GET("/slow", func(c *gin.Context) {
		time.Sleep(10 * time.Millisecond)
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/slow", nil)
	r.ServeHTTP(w, req)
	fmt.Println("状态码:", w.Code)
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// Recovery 兜住后面所有 handler 抛出的 panic
func Recovery() gin.HandlerFunc {
	return func(c *gin.Context) {
		defer func() {
			if err := recover(); err != nil {
				fmt.Println("捕获到 panic:", err)
				c.AbortWithStatusJSON(500, gin.H{"error": "internal server error"})
			}
		}()
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(Recovery()) // 要放在最前面，才能兜住后面所有 handler
	r.GET("/boom", func(c *gin.Context) {
		panic("boom")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/boom", nil)
	r.ServeHTTP(w, req)
	fmt.Printf("code=%d body=%s\n", w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// CORS 只放行白名单里的 Origin，并单独处理预检
func CORS(allowed string) gin.HandlerFunc {
	return func(c *gin.Context) {
		origin := c.GetHeader("Origin")
		if origin == allowed {
			c.Header("Access-Control-Allow-Origin", origin)
			c.Header("Access-Control-Allow-Credentials", "true")
			c.Header("Vary", "Origin")
		}
		if c.Request.Method == http.MethodOptions {
			c.Header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE")
			c.Header("Access-Control-Allow-Headers", "Authorization, Content-Type")
			c.Header("Access-Control-Max-Age", "600")
			c.AbortWithStatus(http.StatusNoContent)
			return
		}
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(CORS("https://app.example.com"))
	r.GET("/api/user", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"id": 1}) })

	for _, method := range []string{http.MethodOptions, http.MethodGet} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(method, "/api/user", nil)
		req.Header.Set("Origin", "https://app.example.com")
		r.ServeHTTP(w, req)
		fmt.Printf("%-7s code=%d allow-origin=%q max-age=%q\n", method, w.Code,
			w.Header().Get("Access-Control-Allow-Origin"),
			w.Header().Get("Access-Control-Max-Age"))
	}
}
